INSERT INTO `page_contents` (`id`, `name`, `slug`, `photo_example`, `data`, `created_at`, `updated_at`) VALUES
(1, 'Konten Header', 'header-homepage', 'photo/page-contents/content_header.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul Header\",\"content\":\"HIMPUNAN MAHASISWA TEKNOLOGI INFORMASI\"},\"2-text2\":{\"type\":\"text\",\"name\":\"Deskripsi Header\",\"content\":\"HIMATIF (Himpunan Mahasiswa Teknologi Informasi) adalah salah satu organisasi mahasiswa di Fakultas Ilmu Komputer, Universitas Jember yang memiliki tujuan pokok meningkatkan kualitas Sumber Daya Mahasiswa Teknologi Informasi.\"},\"3-photo\":{\"type\":\"image\",\"name\":\"Image\",\"content\":\"photo\\/page-contents\\/8jj4qJApFBNNfLayWcinR09OOZ4o834dxNrnL60T.png\"},\"4-marquee_tag\":{\"type\":\"string\",\"name\":\"Marquee Info\",\"content\":\"Info\"},\"5-marquee_info\":{\"type\":\"mediumtext\",\"name\":\"Marquee Konten\",\"content\":\"<p>Open Registrasi Peserta Kompak Dibuka lagi loh !!!!. <a href=\\\"https:\\/\\/bit.ly\\/OpregPesertaKompak\\\"><b>Join Sekarang!<\\/b><\\/a><\\/p>\"}}', NULL, '2025-07-07 14:41:04'),
(2, 'Konten Header Tentang', 'header-about', 'photo/page-contents/content_header_about.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul Header\",\"content\":\"TENTANG HIMATIF\"},\"2-text2\":{\"type\":\"text\",\"name\":\"Deskripsi Header\",\"content\":\"HIMATIF (Himpunan Mahasiswa Teknologi Informasi) adalah Salah satu Organisasi Mahasiswa di Fakultas Ilmu Komputer Universitas Jember. Terbentuknya HIMATIF dirintis oleh 7 Orang Mahasiswa Teknologi Informasi pada tanggal 6 Agustus 2017.\"}}', NULL, NULL),
(3, 'Konten Header Divisi & Pengurus', 'header-pengurus', 'photo/page-contents/content_header_pengurus.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul Header\",\"content\":\"DIVISI DAN PENGURUS\"},\"2-text2\":{\"type\":\"text\",\"name\":\"Deskripsi Header\",\"content\":\"HIMATIF memiliki struktur kepengurusan yang bertanggung jawab atas berbagai aspek dan kegiatan organisasi. Setiap divisi memiliki tugas pokok dan fungsi masing-masing untuk mencapai tujuan organisasi secara keseluruhan.\"}}', NULL, '2024-02-13 12:03:32'),
(4, 'Konten Header Proker', 'header-proker', 'photo/page-contents/content_header_proker.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul Header\",\"content\":\"PROKER HIMATIF\"},\"2-text2\":{\"type\":\"text\",\"name\":\"Deskripsi Header\",\"content\":\"Program kerja HIMATIF merupakan sejumlah kegiatan dan inisiatif yang ditujukan untuk meningkatkan kualitas pendidikan, pengembangan soft skill dan hard skill mahasiswa, serta memperkuat hubungan antar-mahasiswa dan dengan pihak-pihak terkait.\"}}', NULL, '2024-02-13 12:02:11'),
(5, 'Konten Section 2', 'section2-homepage', 'photo/page-contents/content_section2.jpg', '{\"text\":{\"type\":\"string\",\"name\":\"Judul\",\"content\":\"APA YANG KAMI LAKUKAN\"},\"text2\":{\"type\":\"string\",\"name\":\"Sub Judul\",\"content\":\"Kami Berfokus pada pengembangan kualitas Sumber Daya Mahasiswa Teknologi Informasi\"},\"card1_text\":{\"type\":\"string\",\"name\":\"Card 1 Judul\",\"content\":\"Menyusun Proker\"},\"card1_text2\":{\"type\":\"text\",\"name\":\"Card 1 Teks\",\"content\":\"Program kerja dibuat dan dikelola oleh masing-masing divisi di HIMATIF sesuai ruang lingkup masing masing\"},\"card2_text\":{\"type\":\"string\",\"name\":\"Card 2 Judul\",\"content\":\"Melaksanakan Proker\"},\"card2_text2\":{\"type\":\"text\",\"name\":\"Card 2 Teks\",\"content\":\"Program kerja yang telah dirancang, dilaksanakan dan diikuti oleh seluruh elemen di HIMATIF\"},\"card3_text\":{\"type\":\"string\",\"name\":\"Card 3 Judul\",\"content\":\"Meningkatkan Kualitas Sumber Daya Mahasiswa\"},\"card3_text2\":{\"type\":\"text\",\"name\":\"Card 3 Teks\",\"content\":\"Output yang diharapkan pada setiap proker yaitu meningkatnya kualitas Sumber Daya Mahasiswa HIMATIF\"}}', NULL, NULL),
(6, 'Konten Section 3', 'section3-homepage', 'photo/page-contents/content_section3.jpg', '{\"image1\":{\"type\":\"image\",\"name\":\"Image 1\",\"content\":\"photo\\/page-contents\\/ncXxzmRGAldAPkF1y3iEbrU78b302I2tp4Ri6s71.jpg\"},\"image2\":{\"type\":\"image\",\"name\":\"Image 2\",\"content\":\"photo\\/page-contents\\/UdHq6G6JmgR3bg2tkJZtiQJW06qrdsGwsF1eqIh2.jpg\"},\"image3\":{\"type\":\"image\",\"name\":\"Image 3\",\"content\":\"photo\\/page-contents\\/M4sdEfYlIf9z2esTWNDVG5j4kem8e4jpvCvpV4aB.jpg\"}}', NULL, '2025-07-07 15:17:39'),
(7, 'Konten Visi Misi', 'section-vision-mission', 'photo/page-contents/content_vision_mission.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul\",\"content\":\"VISI DAN MISI\"},\"2-text2\":{\"type\":\"string\",\"name\":\"Sub Judul\",\"content\":\"Visi dan Misi Himpunan Mahasiswa Teknologi Informasi\"},\"3-vision_photo\":{\"type\":\"image\",\"name\":\"Gambar Visi\",\"content\":\"photo\\/page-contents\\/llSJi4cvPBlxmwDQIwMWZOo3j6cgz2HMLVTaF5Bm.jpg\"},\"3-vision_text\":{\"type\":\"string\",\"name\":\"Judul Visi\",\"content\":\"VISI\"},\"3-vision_text2\":{\"type\":\"mediumtext\",\"name\":\"Teks Visi\",\"content\":\"<p>Terwujudnya mahasiswa berkarakter serta menjadi media untuk mengembangkan potensi mahasiswa di bidang IPTEK yang didasari tanggung jawab dan sikap profesionalisme.<\\/p>\"},\"4-mission_photo\":{\"type\":\"image\",\"name\":\"Gambar Misi\",\"content\":\"photo\\/page-contents\\/wN3qxg1IEXnwlVHjB0nuXjtbRS3VVSfNfdIXK7V5.jpg\"},\"4-mission_text\":{\"type\":\"string\",\"name\":\"Judul Misi\",\"content\":\"MISI\"},\"4-mission_text2\":{\"type\":\"mediumtext\",\"name\":\"Teks Misi\",\"content\":\"<p><span>1. Mengadakan kegiatan yang bertujuan untuk mengembangkan IPTEK.<\\/span><br><span>2.\\u00a0<\\/span>Meningkatkan\\u00a0 kualitas\\u00a0 sumber daya\\u00a0 manusia\\u00a0 di\\u00a0 bidang\\u00a0 akademis, kewirausahaan, dan keprofesian.<br><span>3. Memperkenalkan\\u00a0 Program Studi Teknologi Informasi\\u00a0 di\\u00a0 lingkungan masyarakat luas.<\\/span><br><span>4. Menjalin\\u00a0 hubungan\\u00a0 dan\\u00a0 kerjasama\\u00a0 atas\\u00a0 dasar\\u00a0 kekeluargaan\\u00a0 dengan organisasi di dalam atau di luar Program Studi Teknologi Informasi.<\\/span><br><span>5. Melaksanakan\\u00a0 setiap\\u00a0 kegiatan\\u00a0 dengan\\u00a0 berlandaskan\\u00a0 kedisiplinan\\u00a0 dan penuh tanggung jawab.<br>6.\\u00a0Mempererat\\u00a0 tali\\u00a0 persaudaraan\\u00a0 antar\\u00a0 mahasiswa\\u00a0 khususnya\\u00a0 anggota HIMATIF.<\\/span><\\/p>\"}}', NULL, '2025-07-07 15:00:25'),
(8, 'Konten Gallery Homepage', 'section-gallery-homepage', 'photo/page-contents/content_gallery_homepage.jpg', '{\"1-image1\":{\"type\":\"image\",\"name\":\"Galeri 1\",\"content\":\"photo\\/page-contents\\/EKflJrmLwA44Nnore2rqnSg6pZZrypj4whK7Ddcn.jpg\"},\"2-image2\":{\"type\":\"image\",\"name\":\"Galeri 2\",\"content\":\"photo\\/page-contents\\/4IbzqarQPvwHmwCOsFLoxGXCYOtsUm9H9x8tMzcO.jpg\"},\"3-image3\":{\"type\":\"image\",\"name\":\"Galeri 3\",\"content\":\"photo\\/page-contents\\/RylmnGrcCnZ7hwMchYfbiY6eR8SMkVjV8abO4VgZ.jpg\"},\"4-image4\":{\"type\":\"image\",\"name\":\"Galeri 4\",\"content\":\"photo\\/page-contents\\/NlOqVLDs0OpWBkoIgvmkdg55ggbGbL3qngP8VFFM.jpg\"},\"5-image5\":{\"type\":\"image\",\"name\":\"Galeri 5\",\"content\":\"photo\\/page-contents\\/O8xhAaOswYAEiPNztFgLFApem0YoVzR2Qvii7M2r.jpg\"}}', NULL, '2025-06-24 22:45:54'),
(9, 'Konten Slogan Himatif', 'section-slogan', 'photo/page-contents/content_slogan.jpg', '{\"1-text\":{\"type\":\"string\",\"name\":\"Judul\",\"content\":\"Slogan HIMATIF\"},\"2-text2\":{\"type\":\"string\",\"name\":\"Sub Judul\",\"content\":\"Slogan Himpunan Mahasiswa Teknologi Informasi\"},\"3-slogan\":{\"type\":\"string\",\"name\":\"Slogan Himatif\",\"content\":\"\\u201c MUDA, TIDAK MENYERAH! \\u201d\"}}', NULL, NULL);
INSERT INTO `pemilu_candidates` (`id`, `nama`, `nim`, `photo`, `visi`, `misi`, `created_at`, `updated_at`) VALUES
(1, 'Muhammad Hanif P', '232410102090', 'photo/candidate/zwZqYVoN12I0zxdRmpsjrhWrM4tK5p809Fy7pjjD.png', 'Mewujudkan HIMATIF sebagai organisasi yang nyaman, inklusif, dan profesional, dengan lingkungan kerja yang efisien serta berorientasi pada kontribusi nyata bagi seluruh mahasiswa Teknologi Informasi Fasilkom.', '[\"1. Membangun lingkungan organisasi yang nyaman dan suportif\",\"2. Meningkatkan efisiensi fungsi dan tata kelola HIMATIF\",\"3. Memperkuat kontribusi HIMATIF bagi mahasiswa TI\"]', '2025-07-08 19:09:44', '2025-12-01 02:33:45'),
(2, 'Muhammad Aka S', '232410102028', 'photo/candidate/W3Xsvuy6GssnTGnwVCVkLMZXbltkr0j8wwN9skUg.png', 'Mewujudkan HIMATIF sebagai organisasi yang nyaman, aman, dan penuh rasa kekeluargaan, yang mampu menumbuhkan semangat belajar, meningkatkan kualitas Teknologi Informasi, serta terus mengevaluasi dan mengoptimalkan efektivitas kinerja program kerja demi kesejahteraan seluruh pengurus dan anggota.', '[\"1. Membangun lingkungan organisasi yang kondusif, kekeluargaan yang kuat, serta menjunjung kenyamanan bagi seluruh anggota dan pengurus HIMATIF.\",\"2. Menanamkan semangat belajar dan mendorong perkembangan kompetensi Teknologi Informasi melalui program kerja yang inovatif dan berkelanjutan.\",\"3. Memperbaiki dan melanjutkan hasil evaluasi yang ada untuk meningkatkan efektivitas seluruh program kerja HIMATIF sehingga organisasi dapat semakin maju, responsif, dan relevan.\"]', '2025-07-08 19:10:02', '2025-12-01 02:33:55');
