INSERT INTO `reviews` (`id`, `name`, `nim`, `phone`, `angkatan`, `tempat_kerja`, `experience`, `motivation`, `instagram`, `photo`, `created_at`, `updated_at`) VALUES
(26, 'Kukuh Tri Winarno Nugroho, S.Kom', '172410102064', 'wa.me/6282232161707', 2023, 'Corsiva Lab Pte Ltd', 'Kuliah di prodi TI Fasilkom sangat baik, pegawai TU dan dosen baik, ramah, dan memudahkan. Namun, perlu untuk terus meningkatkan kurikulum pembelajaran.', 'jangan mudah menyerah ,karena seseorang bisa sukses bukan karena tidak pernah gagal, tetapi karena setiap dia gagal dia bisa maju terus sampai berhasil. dan jangan lupa berdoa dan meminta ridho orang tua', 'ig: @kukuhtriw', 'reviews/1750807070.jpg', '2025-06-24 23:03:58', '2025-06-24 23:17:50'),
(27, 'RIZAL AKBAR ARIFIN', '182410102044', 'wa.me/6282139338702', 2023, 'CIMB Niaga', 'Kuliah di prodi TI UNEJ sangat mengesankan, materi kuliah menarik untuk dipelajari, dosen dan juga teman-teman yang sangat membantu dan suportif satu sama lain.', 'tetep semangat terus dalam menimba ilmu, cari koneksi sebanyak banyak nyaa, ingat pengalaman di kuliah itu sangat berharga untuk kedepannya, jadi jangan lewatkan kesempatan itu yaa', NULL, 'reviews/1750806917.png', '2025-06-24 23:06:02', '2025-06-24 23:15:17'),
(28, 'METRI PANGESTIKA', '162410102039', 'wa.me/6282257895893', 2023, 'Design Pickle', 'Selama kuliah seru sihh, banyak banget pengalaman baru yang ku dapat. Mulai dari matkul yang inovatif, serta relasi yang sangat membantu banget buat di dunia kerja.', 'Untuk adik² Podi TI, selama kalian masi di lingkungan kampus gunain dan manfaatin sebaik mungkin untuk improve skill sebanyak²nya, cari temen, kating dan koneksi yang bisa bantu kamu level up. Di kampus ipk emang penting tapi yang lebih penting adalah skill pas uda lulus. So manfaatin aja selama kalian kuliah sebaik mungkin dan semangat buat adik² prodi TI', 'IG: metri112', 'reviews/1750807061.jpg', '2025-06-24 23:07:34', '2025-06-24 23:17:41'),
(29, 'I\'ZAZ DHIYA \'ULHAQ', '192410102033', 'wa.me/6282323731302', 2023, 'PT. Nusantara Berkah Digital', 'Karena awal kuliah terdampak Covid-19, saya dapat belajar lebih banyak hal dengan memanfaatkan media online, aktif organisasi, dan mengikuti MBKM. Saat kuliah offline, saya mengikuti program Digistar (Digital Startup) yang sangat bermanfaat untuk mengembangkan dan mewujudkan ide usaha.', 'Ambil kesempatan apapun itu yang bisa bikin kita semakin berkembang', 'IG: izazdhiyaa', 'reviews/1750807079.jpg', '2025-06-24 23:08:49', '2025-06-24 23:17:59'),
(30, 'WHINAR KUKUH RIZKY ARDANA', '192410102041', 'wa.me/6282139114771', 2023, 'FMCG', 'Selama studi di Fasilkom aku merasa cukup terfasilitasi, dari mata kuliah pilihan sesuai minat, kemudahan mengikuti program kampus merdeka yang sangat berguna sekali buat kita belajar lebih jauh dan dapetin pengalaman langsung di dunia kerja.', 'Jangan berhenti belajar aja pokoknya, it’s not going to be easy but it’s going to be worthy', 'IG: ardanarizky_', 'reviews/1758205075.php', '2025-06-24 23:16:46', '2025-09-18 14:17:55');
